enum {
    FEMENU_SCROLLING = 0x001,
    FEMENU_DONT_SHOW_DISABLED = 0x400
};

struct entry_vtable {
    char padding[0x30];
    short disable_adjust;
    short disable_reserved;
    bool (*get_disable)(void *);
    short draw_adjust;
    short draw_reserved;
    void (*draw)(void *);
};

class FEMenuEntry {
public:
    int entry_num;
    FEMenuEntry *next;

private:
    char padding[0x58];
    entry_vtable *vtable;

public:
    bool GetDisable()
    {
        return vtable->get_disable((char *)this + vtable->disable_adjust);
    }

    void Draw()
    {
        vtable->draw((char *)this + vtable->draw_adjust);
    }
};

struct menu_vtable {
    char padding[0x40];
    short draw_adjust;
    short draw_reserved;
    void (*draw)(void *);
};

struct menu_layout {
    char padding[0x74];
    menu_vtable *vtable;
};

class TextString {
    char padding[0x24];
    menu_vtable *vtable;

public:
    void Draw()
    {
        vtable->draw((char *)this + vtable->draw_adjust);
    }
};

class FEMenu {
    char padding0[0x38];
    int max_vis_entries;
    int flags;
    FEMenuEntry *entries;
    FEMenuEntry *first_vis_entry;
    char padding1[0x18];
    menu_layout *active;
    char padding2[4];
    TextString *helpText;

public:
    void Draw();
};

void FEMenu::Draw()
{
    if (active != 0) active->vtable->draw(
        (char *)active + active->vtable->draw_adjust);
    else
    {
        if (!(flags & FEMENU_SCROLLING))
        {
            FEMenuEntry *tmp = entries;
            while (tmp != 0)
            {
                if (!(flags & FEMENU_DONT_SHOW_DISABLED && tmp->GetDisable()))
                    tmp->Draw();
                tmp = tmp->next;
            }
        }
        else
        {
            FEMenuEntry *tmp = first_vis_entry;
            int count = max_vis_entries;
            while (count > 0)
            {
                count--;
                if (!tmp) tmp = entries;
                while (flags & FEMENU_DONT_SHOW_DISABLED && tmp->GetDisable())
                {
                    tmp = tmp->next;
                    if (tmp == 0) tmp = entries;
                }
                tmp->Draw();
                tmp = tmp->next;
            }
        }
        helpText->Draw();
    }
}
